/**
 * SettlementRoadMesh.ts — 02-game-world-integration (SI-2)
 *
 * Builds road/path surface meshes for a settlement's building layout
 * (SI-1, `SettlementSpawner.ts`'s `SettlementSpawnPlan`).
 *
 * Deviation from the spec's literal "settlement roads from OW-A road
 * network" (the Studio's Chaikin-smoothed `Road[]` in `SettlementModel`,
 * generated by the DOM-coupled `generateSettlementModel` in
 * `overworld-studio.ts`): SI-1 deliberately doesn't reuse that ward/road
 * system, so there is no smoothed road network to draw. Instead this module
 * generates a simple spoke layout matching SI-1's concentric-ring building
 * placement — one straight ribbon from the settlement centre to each
 * building — which is the natural road network for that placement style
 * (same category of pragmatic substitution as RI-3's ribbon-not-tube river
 * and SI-1's ring-not-ward layout).
 *
 * Same width-varying quad-strip-ribbon technique used elsewhere for
 * settlement roads/ribbons (see `SettlementRenderer.ts`),
 * but flat width per segment (roads don't taper) with width chosen by
 * "importance" per SI-2: buildings that anchor a settlement (guild, inn,
 * tavern, chapel, well/plaza) get a 2 world-unit "main road"; everything
 * else gets a 1 world-unit "alley".
 *
 * Uses the existing `cobblestoneTexture()` (`src/world/buildings/
 * TextureFactory.ts`) for the road surface — that module is lazy/canvas-based
 * with no top-level DOM side effects, so (unlike `overworld-studio.ts`) it's
 * safe to import as a runtime value, not just a type.
 */

import * as THREE from 'three';
import { cobblestoneTexture } from './buildings/TextureFactory';
import { CORNER_JITTER_MAX } from './TerrainGeometryBuilder';
import type { SettlementSpawnPlan, WorldPos2 } from './SettlementSpawner';
import type { RiverHeightSampler } from './HeightSampler';
import type { BuildingKind } from './buildings/BuildingDNA';

/** World-unit width of a "main road" — connects settlement-anchor buildings. */
export const MAIN_ROAD_WIDTH = 2;

/** World-unit width of an "alley" — connects minor buildings. */
export const ALLEY_WIDTH = 1;

/** Vertical offset above the sampled terrain height, avoids z-fighting with
 *  the ground plane. Must clear TerrainGeometryBuilder's CORNER_JITTER_MAX
 *  (the terrain top face's own per-corner cosmetic jitter) — kept in sync
 *  with SettlementRenderer.ts's own ROAD_HEIGHT_OFFSET. */
export const ROAD_HEIGHT_OFFSET = CORNER_JITTER_MAX + 0.02;

/** Building kinds considered settlement anchors (get the wider "main road"). */
const MAIN_ROAD_KINDS: ReadonlySet<BuildingKind> = new Set<BuildingKind>([
  'guild', 'inn', 'tavern', 'chapel', 'well', 'gate',
]);

export interface RoadSegmentPlan {
  from: WorldPos2;
  to: WorldPos2;
  width: number;
}

/**
 * SI-2 — derive one road segment per non-centre building: a straight spoke
 * from the settlement centre to that building, widened for anchor kinds.
 * Pure data — no Three.js.
 */
export function planSettlementRoads(plan: SettlementSpawnPlan): RoadSegmentPlan[] {
  const segments: RoadSegmentPlan[] = [];
  for (const building of plan.buildings) {
    // Skip the building placed exactly at the centre (SI-1's well/plaza
    // marker) — there's nothing to connect it to itself.
    if (building.position.x === plan.position.x && building.position.z === plan.position.z) continue;
    const width = MAIN_ROAD_KINDS.has(building.dna.buildingKind) ? MAIN_ROAD_WIDTH : ALLEY_WIDTH;
    segments.push({ from: plan.position, to: building.position, width });
  }
  return segments;
}

export interface BuiltSettlementRoads {
  /** Three.js root group — add to scene with `scene.add(roads.root)`. */
  root: THREE.Group;
  /** Release GPU resources. */
  dispose(): void;
}

export interface BuildSettlementRoadsOptions {
  /** World-space height sampler (e.g. RI-1's `makeHeightSampler()`) — defaults to flat (0). */
  heightAt?: RiverHeightSampler;
  /** Cobblestone texture repeat scale per world unit of road length. */
  textureRepeatPerUnit?: number;
}

/**
 * SI-2 — build flat quad-strip ribbon meshes for a settlement's road plan,
 * one mesh per segment, textured with the existing cobblestone canvas
 * texture (tiled along the road's length).
 */
export function buildSettlementRoads(
  plan: SettlementSpawnPlan,
  options: BuildSettlementRoadsOptions = {},
): BuiltSettlementRoads {
  const heightAt = options.heightAt ?? (() => 0);
  const repeatPerUnit = options.textureRepeatPerUnit ?? 0.5;

  const root = new THREE.Group();
  const geometries: THREE.BufferGeometry[] = [];
  const materials: THREE.Material[] = [];

  for (const segment of planSettlementRoads(plan)) {
    const dx = segment.to.x - segment.from.x;
    const dz = segment.to.z - segment.from.z;
    const length = Math.hypot(dx, dz);
    if (length < 1e-6) continue;

    const dirX = dx / length, dirZ = dz / length;
    const rightX = -dirZ, rightZ = dirX; // perpendicular ("right") vector
    const halfWidth = segment.width / 2;

    const y0 = heightAt(segment.from.x, segment.from.z) + ROAD_HEIGHT_OFFSET;
    const y1 = heightAt(segment.to.x, segment.to.z) + ROAD_HEIGHT_OFFSET;

    const positions = [
      segment.from.x + rightX * halfWidth, y0, segment.from.z + rightZ * halfWidth,
      segment.from.x - rightX * halfWidth, y0, segment.from.z - rightZ * halfWidth,
      segment.to.x + rightX * halfWidth,   y1, segment.to.z + rightZ * halfWidth,
      segment.to.x - rightX * halfWidth,   y1, segment.to.z - rightZ * halfWidth,
    ];
    const uvRepeat = Math.max(1, Math.round(length * repeatPerUnit));
    const uvs = [0, 0, 1, 0, 0, uvRepeat, 1, uvRepeat];
    const indices = [0, 2, 1, 1, 2, 3];

    const geometry = new THREE.BufferGeometry();
    geometry.setAttribute('position', new THREE.Float32BufferAttribute(positions, 3));
    geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
    geometry.setIndex(indices);
    geometry.computeVertexNormals();
    geometries.push(geometry);

    const material = new THREE.MeshStandardMaterial({
      map: cobblestoneTexture(1, uvRepeat), roughness: 0.9, metalness: 0,
    });
    materials.push(material);

    const mesh = new THREE.Mesh(geometry, material);
    mesh.receiveShadow = true;
    mesh.userData['roadWidth'] = segment.width;
    root.add(mesh);
  }

  return {
    root,
    dispose: () => {
      for (const g of geometries) g.dispose();
      for (const m of materials) m.dispose();
    },
  };
}
